/* Provider-owned payment fields. Academy code never receives card number/CVC. */
(()=>{'use strict';const esc=window.AcademyStandard.esc,link=(label,route,primary=false)=>`<a class="btn ${primary?'primary':''}" href="#${route}">${esc(label)}</a>`,money=(p)=>window.AcademyReceipt.money(p.amount,p.currency);let ctx,chosen='',live=null,actions=null;
function card(sample=false){return `<div class="payment-visual"><div class="payment-card" id="payment-card"><div class="card-front"><span class="small">DIGITALBURJ ACADEMY</span><span class="card-brand" id="card-brand">VISA / Mastercard</span><div class="card-chip" aria-hidden="true"></div><div class="card-number" id="card-number">•••• •••• •••• ••••</div><div class="card-bottom"><span id="card-holder">${sample?'SAMPLE CARD':'SECURE CARD ENTRY'}</span><span id="card-expiry">MM / YY</span></div></div><div class="card-back"><div class="card-stripe"></div><div class="card-signature" id="card-cvc">•••</div><p class="small">${sample?'Visual sample only':'Protected by your payment provider'}</p></div></div></div>`}
function plan(p,c){return `<article><span class="status">${p.teachingPlan?'With dedicated teacher':'Self-paced'}</span><h3>${esc(p.title)}</h3><p><b>${esc(money(p))}</b> · ${p.durationDays} days of course access</p><p class="small muted">${p.courseIds.map(id=>esc(c.track(id)?.title||id)).join(' · ')}</p>${p.teachingPlan?'<p class="small">8 weeks · 24 private classes · 3 classes/week · 2 hours/class · 48 hours of teaching</p>':''}${link('Review purchase','checkout/'+p.id,true)}</article>`}
async function shop(id,c){const selected=c.track(id),products=(c.session?.products||[]).filter(p=>!selected||p.courseIds.includes(id));let orders=[];if(c.mode==='connected'){const r=await fetch('/api/orders');const b=await r.json();if(!r.ok)throw Error(b.error);orders=b.items}return `<div class="page-head"><div><h1>${selected?'Join '+esc(selected.title):'Course access & orders'}</h1><p>Choose your course, review its terms, then pay securely.</p></div>${link('Browse courses','paths')}</div><ol class="checkout-progress"><li class="current">1. Choose your package</li><li>2. Secure payment</li><li>3. Receipt & access</li></ol><label class="field"><span>Course</span><select id="checkout-course"><option value="">Choose a course</option>${c.atlas.tracks.map(t=>`<option value="${t.id}" ${id===t.id?'selected':''}>${esc(t.title)}${t.free?' · Free':''}</option>`).join('')}</select></label>${selected?.free?`<section class="panel"><h2>This course is free.</h2><p>You can start its lessons and use the practice tools without a purchase.</p>${link('Open free course','path/'+id,true)}</section>`:products.length?`<div class="purchase-plan">${products.map(p=>plan(p,c)).join('')}</div>`:`<section class="panel"><h2>Paid enrolment is not open yet.</h2><p class="muted">${selected?'This course is in the catalogue; purchasing will open when its enrolment options are available.':'Choose a course to see its available bundles.'} Your free foundations and practice workspace are available now.</p><div class="row">${link('Start free foundations','path/start',true)}${link('Use practice tools','studio')}</div></section>`}<div class="section-title"><h2>How your access works</h2></div><p class="muted">Confirmed payment unlocks the courses included in your package. Your receipt is saved with the order. Teacher bundles add class booking; certificates follow assessment.</p><div class="section-title"><h2>Your orders & receipts</h2></div>${orders.length?`<div class="journey-list">${orders.map(o=>`<a class="journey-item" href="#receipt/${encodeURIComponent(o.id)}"><div class="journey-content"><b>${esc(o.title)}</b><small>${new Date(o.created).toLocaleDateString()} · ${esc(money(o))}</small></div><span class="status">${esc(o.status)}</span></a>`).join('')}</div>`:'<section class="panel"><p class="muted">No orders yet. Only actual purchase attempts appear here.</p></section>'}${c.mode==='preview'?`<details class="session-plan"><summary>Preview the payment experience</summary><p class="small muted" style="margin-top:18px">These samples make no charge and grant no access.</p><div class="row">${link('Animated card preview','checkout/demo')}${link('Receipt printer preview','receipt/demo')}</div></details>`:''}`}
const methodNames={razorpay:'Razorpay · INR',stripe:'Card / Google Pay',gumroad:'Gumroad',binance:'Binance Pay',crypto:'Other crypto wallets'};
async function page(id,c){live=null;actions=null;if(id==='demo'){return `<div class="page-head"><div><h1>Animated card preview</h1><p>Try the card interaction using fictional test digits.</p></div>${link('Back to course access','shop')}</div><div class="checkout-overview checkout-sample"><section class="panel"><p class="payment-preview-label">VISUAL SAMPLE · NO PAYMENT · NO COURSE ACCESS</p><h2>The card follows your input.</h2><p class="small muted">Use a Stripe test number beginning 4242 (Visa) or 5555 (Mastercard). These fields exist only in this visual preview. Real checkout uses the payment provider’s protected fields.</p><div class="preview-card-fields"> <label class="field wide"><span>Test card number</span><input id="preview-card-number" inputmode="numeric" autocomplete="off" maxlength="23" placeholder="4242 4242 4242 4242"></label><label class="field wide"><span>Sample name</span><input id="preview-card-name" maxlength="40" autocomplete="off" placeholder="Practice Learner"></label><label class="field"><span>Sample expiry</span><input id="preview-card-expiry" inputmode="numeric" maxlength="7" autocomplete="off" placeholder="12 / 30"></label><label class="field"><span>Sample CVC</span><input id="preview-card-cvc" inputmode="numeric" maxlength="3" autocomplete="off" placeholder="123"></label></div><p id="payment-message" class="small" role="status">No sample input is stored or sent.</p></section><aside class="sample-card-preview"><span class="sample-card-notice">VISUAL SAMPLE · NO PAYMENT</span>${card(true)}<p class="small muted">The live card animation reacts to payment method and completion. Full card numbers stay inside the provider’s secure frame.</p></aside></div>`}
const p=(c.session?.products||[]).find(p=>p.id===id);if(!p)throw Error('This enrolment option is not available. Return to the course catalogue.');const config=await c.api('payment/config');chosen=(p.providers||[])[0]||'';return `<div class="page-head"><div><h1>Review your purchase</h1><p>${esc(p.title)}</p></div>${link('Change package','shop/'+p.courseIds[0])}</div><ol class="checkout-progress"><li>1. Choose your package</li><li class="current">2. Secure payment</li><li>3. Receipt & access</li></ol><div class="checkout-overview"><section class="panel checkout-sheet"><h2>${esc(money(p))}</h2><p>${p.courseIds.map(t=>esc(c.track(t)?.title||t)).join(' · ')}</p><p class="small muted">Course access: ${p.durationDays} days from confirmed payment.${p.teachingPlan?' Private teaching: 8 weeks, 24 two-hour classes, three classes per week.':''}</p><h3>Choose a payment method</h3><div class="provider-list">${Object.entries(methodNames).map(([id,label])=>`<button class="provider-option" data-payment-provider="${id}" aria-pressed="${id===chosen}" ${p.providers?.includes(id)?'':'disabled'}><b>${label}</b><span>${p.providers?.includes(id)?id==='stripe'?'Visa, Mastercard & eligible wallets':id==='razorpay'?'Cards, UPI & eligible merchant wallets':'Available':'Not available for this purchase'}</span></button>`).join('')}</div>${p.providers?.includes('crypto')?`<label class="field" id="crypto-asset-field" ${chosen==='crypto'?'':'hidden'}><span>Crypto asset & network</span><select id="crypto-asset">${config.assets.map(a=>`<option value="${esc(a.id)}">${esc(a.label)}</option>`).join('')}</select></label>`:''}<details><summary>Purchase and refund terms</summary><p class="small" style="margin-top:14px">${esc(p.refundPolicy)}</p><a href="${esc(p.termsUrl)}" target="_blank" rel="noopener noreferrer">Read complete purchase terms</a></details><label class="checkbox"><input id="checkout-terms" type="checkbox">I have reviewed and accept the purchase and refund terms.</label><button class="btn primary" id="prepare-payment" data-product="${esc(p.id)}" ${chosen?'':'disabled'}>Continue to secure payment</button><div id="secure-payment" style="margin-top:24px"></div><p id="payment-message" role="status" class="small" style="margin-top:16px"></p></section><aside>${card()}<section class="panel"><h3>After your payment</h3><p class="small muted">We confirm the provider’s payment record. Then your receipt prints on screen and the purchased courses appear in My courses.</p><p class="small muted">Google Pay appears when supported by your device, region and merchant settings. External subscriptions are purchased separately.</p></section></aside></div>`}
async function loadRazorpay(){if(window.Razorpay)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=()=>window.Razorpay?resolve():reject(Error('The secure merchant checkout could not initialize.'));script.onerror=()=>reject(Error('The secure merchant checkout could not load. Check your connection and retry.'));document.head.append(script)})}
async function loadStripe(){if(window.Stripe)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://js.stripe.com/v3/';script.onload=resolve;script.onerror=()=>reject(Error('The secure payment form could not load. Retry when your connection is available.'));document.head.append(script)})}
function safeRedirect(url,provider){const u=new URL(url),valid=provider==='stripe'?u.hostname==='checkout.stripe.com':provider==='gumroad'?u.hostname==='gumroad.com'||u.hostname.endsWith('.gumroad.com'):u.hostname.endsWith('.binance.com');if(u.protocol!=='https:'||!valid)throw Error('Unexpected payment destination.');location.assign(u.href)}
function mount(c){ctx=c;document.getElementById('checkout-course')?.addEventListener('change',e=>location.hash='shop/'+e.target.value);document.querySelectorAll('[data-payment-provider]').forEach(b=>b.onclick=()=>{if(live)return;chosen=b.dataset.paymentProvider;document.querySelectorAll('[data-payment-provider]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const field=document.getElementById('crypto-asset-field');if(field)field.hidden=chosen!=='crypto';document.getElementById('card-brand').textContent=chosen==='stripe'?'VISA / Mastercard':methodNames[chosen];document.getElementById('payment-card').classList.toggle('card-active',chosen==='stripe')});
document.querySelectorAll('.preview-card-fields input').forEach(input=>{input.addEventListener('input',()=>{if(input.id==='preview-card-number'){const raw=input.value.replace(/\D/g,'').slice(0,16);if(raw.length>=4&&!raw.startsWith('4242')&&!raw.startsWith('5555')){input.value='';document.getElementById('payment-message').textContent='Use fictional test digits beginning 4242 or 5555.';return}input.value=raw.replace(/(.{4})/g,'$1 ').trim();document.getElementById('card-number').textContent=input.value||'•••• •••• •••• ••••';document.getElementById('card-brand').textContent=raw.startsWith('5')?'Mastercard':raw?'VISA':'VISA / Mastercard';document.getElementById('payment-card').classList.add('card-active')}if(input.id==='preview-card-name')document.getElementById('card-holder').textContent=input.value||'SAMPLE CARD';if(input.id==='preview-card-expiry'){const n=input.value.replace(/\D/g,'').slice(0,4);input.value=n.slice(0,2)+(n.length>2?' / '+n.slice(2):'');document.getElementById('card-expiry').textContent=input.value||'MM / YY'}if(input.id==='preview-card-cvc'){input.value=input.value.replace(/\D/g,'').slice(0,3);document.getElementById('card-cvc').textContent=input.value||'•••'}});input.addEventListener('focus',()=>document.getElementById('payment-card').classList.toggle('card-flipped',input.id==='preview-card-cvc'));input.addEventListener('blur',()=>document.getElementById('payment-card').classList.remove('card-flipped'))});
const prepare=document.getElementById('prepare-payment');if(prepare)prepare.onclick=async()=>{const status=document.getElementById('payment-message');if(!document.getElementById('checkout-terms').checked){status.textContent='Read and accept the displayed purchase and refund terms first.';return}prepare.disabled=true;try{let key;try{key=sessionStorage.getItem('dba-checkout-key-'+prepare.dataset.product+'-'+chosen)||crypto.randomUUID();sessionStorage.setItem('dba-checkout-key-'+prepare.dataset.product+'-'+chosen,key)}catch{key=crypto.randomUUID()}live=await ctx.api('payment/session','POST',{productId:prepare.dataset.product,provider:chosen,requestKey:key,acceptTerms:true,expectedTerms:ctx.session.products.find(p=>p.id===prepare.dataset.product)?.purchaseTerms,payCurrency:document.getElementById('crypto-asset')?.value});try{sessionStorage.setItem('dba-pending-order',live.orderId)}catch{}document.querySelectorAll('[data-payment-provider]').forEach(b=>b.disabled=true);const host=document.getElementById('secure-payment');
if(chosen==='razorpay'){status.textContent='Opening secure INR checkout…';await loadRazorpay();const order=live;host.innerHTML='<button class="btn primary" id="reopen-razorpay">Open secure payment</button>';const merchantCheckout=new window.Razorpay({key:order.keyId,amount:order.amount,currency:order.currency,name:order.businessName,description:order.title,order_id:order.providerOrderId,prefill:{name:ctx.session.user.name,email:ctx.session.user.email},theme:{color:'#c9260e'},handler:async result=>{status.textContent='Checking the captured payment with your merchant…';try{const verified=await ctx.api('payment/razorpay/confirm','POST',{orderId:order.orderId,providerOrderId:result.razorpay_order_id,paymentId:result.razorpay_payment_id,signature:result.razorpay_signature});if(verified.paid)Object.assign(ctx.session,await ctx.api('bootstrap'));location.hash='receipt/'+order.orderId}catch(err){status.textContent=err.message;host.innerHTML='<a class="btn" href="#receipt/'+encodeURIComponent(order.orderId)+'">Check this order</a>'}},modal:{ondismiss:()=>{status.textContent='Checkout closed. Reopen it to continue, or check this order if you already completed payment.'}}});merchantCheckout.on('payment.failed',()=>{status.textContent='The payment was not confirmed. Check your order before trying again.'});document.getElementById('reopen-razorpay').onclick=()=>merchantCheckout.open();merchantCheckout.open();document.getElementById('card-brand').textContent='Razorpay · INR';document.getElementById('card-holder').textContent='PROTECTED MERCHANT CHECKOUT';document.getElementById('payment-card').classList.add('card-active')}
if(chosen==='stripe'){status.textContent='Loading protected payment fields…';await loadStripe();const stripe=window.Stripe(live.publishableKey),checkout=stripe.initCheckoutElementsSdk({clientSecret:live.clientSecret,elementsOptions:{appearance:{theme:'stripe',variables:{colorPrimary:'#c9260e',fontFamily:'system-ui, sans-serif',borderRadius:'8px'}}}});const loaded=await checkout.loadActions();if(loaded.type!=='success')throw Error('The payment form could not initialize. Your order is unpaid.');actions=loaded.actions;host.innerHTML='<div id="payment-element"></div><button class="btn primary" id="confirm-payment" style="margin-top:22px">Pay securely</button>';const element=checkout.createPaymentElement({layout:'accordion'});element.mount('#payment-element');element.on('change',e=>{document.getElementById('payment-card').classList.toggle('card-active',e.complete);document.getElementById('card-brand').textContent=e.value?.type==='card'?'VISA / Mastercard':e.value?.type||'Secure payment';document.getElementById('card-holder').textContent=e.complete?'DETAILS COMPLETE':'SECURE CARD ENTRY'});document.getElementById('confirm-payment').onclick=async e=>{e.target.disabled=true;status.textContent='Confirming securely…';try{const result=await actions.confirm();if(result.type==='error')throw Error(result.error.message);location.hash='receipt/'+live.orderId}catch(err){status.textContent=err.message;e.target.disabled=false}};status.textContent='Enter payment details in the protected fields. The Academy cannot read or store the card number.'}
if(chosen==='binance'){safeRedirect(live.url,'binance')}
if(chosen==='gumroad'){host.innerHTML=`<h3>Complete purchase with Gumroad</h3><p class="small">Use the same email as your Academy account. After purchase, enter the purchase ID from your Gumroad receipt to link your course access.</p><a class="btn primary" href="${esc(live.url)}" target="_blank" rel="noopener noreferrer">Open Gumroad checkout</a><form id="gumroad-claim" style="margin-top:22px"><label class="field"><span>Gumroad purchase ID</span><input name="saleId" autocomplete="off" maxlength="120" required></label><button class="btn">Verify my purchase</button></form>`;document.getElementById('gumroad-claim').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await ctx.api('payment/gumroad/claim','POST',{orderId:live.orderId,saleId:new FormData(e.target).get('saleId')});location.hash='receipt/'+live.orderId}catch(err){status.textContent=err.message;b.disabled=false}};status.textContent='Access is granted only after the provider’s purchase record is verified.'}
if(chosen==='crypto'){host.innerHTML=`<h3>${esc(live.assetLabel)}</h3><p class="small">Send exactly <b>${esc(live.payAmount)} ${esc(live.payCurrency.toUpperCase())}</b> using the network named above. Other assets or networks may not be recoverable.</p><div class="computed-output">${esc(live.payAddress)}</div><div class="cert-qr" id="wallet-qr" style="margin:20px 0"></div><button class="btn primary" id="check-wallet">Check payment status</button>`;document.getElementById('wallet-qr').innerHTML=window.CertificateCodes.qr(live.payAddress);document.getElementById('check-wallet').onclick=async e=>{e.target.disabled=true;try{const r=await ctx.api('payment/status','POST',{orderId:live.orderId});if(r.paid)location.hash='receipt/'+live.orderId;else status.textContent='Provider status: '+r.status+'. Access will open after final confirmation.'}catch(err){status.textContent=err.message}finally{e.target.disabled=false}};status.textContent='Your payment is awaiting provider confirmation.'}
prepare.hidden=true;
}catch(err){status.textContent=err.message;live=null;prepare.disabled=false}}}
window.AcademyCheckout={shop,page,mount};
})();
